<?php
require_once __DIR__ . '/includes.php'; $posts=db()->query("SELECT * FROM posts WHERE status='published' ORDER BY created_at DESC")->fetchAll(); $groups=[]; foreach($posts as $p){$key=date('Y-m',strtotime($p['created_at']));$groups[$key][]=$p;}
page_header('الأرشيف','أرشيف المقالات حسب الشهر والسنة.'); ?><section class="pageintro"><span class="eyebrow">كل ما نُشر</span><h1>الأرشيف</h1><p>المقالات مرتبة من الأحدث إلى الأقدم.</p></section><?php foreach($groups as $month=>$items): ?><section class="archive-month"><h2><?=e($month)?></h2><?php foreach($items as $post): ?><article class="archive-item"><time><?=e(date('d M Y',strtotime($post['created_at'])))?></time><div><a class="eyebrow" href="category.php?name=<?=rawurlencode($post['category'])?>"><?=e($post['category'])?></a><h3><a href="<?=e(article_url($post))?>"><?=e($post['title'])?></a></h3><small><?=e($post['author'])?></small></div></article><?php endforeach; ?></section><?php endforeach; ?><?php if(!$posts): ?><p class="empty">سيظهر الأرشيف هنا عند نشر المقالات.</p><?php endif; ?><?php page_footer(); ?>
